#!/bin/sh
# Generated by FWShift: an AWS Network Firewall policy and its stateful rule group, created with the AWS CLI. Read the
# report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE    prints the calls, makes none (no AWS access needed)
#   CHECK=1 sh THIS_FILE      sends every call with --dry-run: AWS checks the requests and the permissions
#   sh THIS_FILE              creates the rule group and the policy
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The policy is attached to no firewall: nothing changes for any traffic until you associate it:
#   aws network-firewall associate-firewall-policy --firewall-name FIREWALL --firewall-policy-arn ARN
# A rule group or policy of the same name stops the script before anything is created; a call AWS refuses stops it
# where it is (delete what it made with aws network-firewall delete-rule-group / delete-firewall-policy and run it
# again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws network-firewall' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
TMP=$(mktemp -d) || fail "mktemp"
trap 'rm -rf "$TMP"' EXIT
# free_group NAME / free_policy NAME: stop the script when one of that name exists
free_group() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-rule-group --rule-group-name "$1" --type STATEFUL $AWS_OPTS >/dev/null 2>&1; then
    fail "a rule group named $1 exists already; nothing was created"
  fi
}
free_policy() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-firewall-policy --firewall-policy-name "$1" $AWS_OPTS >/dev/null 2>&1; then
    fail "a firewall policy named $1 exists already; nothing was created"
  fi
}
# group NAME CAPACITY FILE: creates a stateful rule group and prints its ARN
group() {
  if [ -n "$DRY_RUN" ]; then
    show create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3"
    printf 'arn:aws:network-firewall:dryrun:000000000000:stateful-rulegroup/%s\n' "$1"
    return 0
  fi
  if [ -n "$CHECK" ]; then
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --dry-run --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1 (dry run)"
    printf 'checked: rule group %s\n' "$1" >&2
  else
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --description 'Generated by FWShift' --tags Key=fwshift,Value=generated \
      --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1"
    printf 'created %s\n' "$arn" >&2
  fi
  printf '%s\n' "$arn"
}
# policy NAME FILE CHECKFILE: creates the firewall policy (with CHECK, checks it without its rule groups, which a dry run
# does not create)
policy() {
  if [ -n "$DRY_RUN" ]; then show create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2"; return 0; fi
  if [ -n "$CHECK" ]; then
    aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$3" --dry-run $AWS_OPTS >/dev/null \
      || fail "create-firewall-policy $1 (dry run)"
    printf 'checked: firewall policy %s\n' "$1" >&2
    return 0
  fi
  aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2" \
    --description 'Generated by FWShift; review the conversion report before associating it' \
    --tags Key=fwshift,Value=generated $AWS_OPTS >/dev/null || fail "create-firewall-policy $1"
  printf 'created firewall policy %s\n' "$1" >&2
}

# No rule group or policy of these names may exist.
free_group fwshift-rules
free_policy fwshift

# Rule group 1: 5 rules, in the order of the policy.
cat > "$TMP/group1.json" <<'FWSHIFT_JSON'
{
 "RuleVariables": {
  "IPSets": {
   "VLAN_30_": {
    "Definition": [
     "10.10.30.0/24"
    ]
   }
  }
 },
 "RulesSource": {
  "RulesString": "drop tcp any any -> any 23 (msg:\"layer 7 rule 2\"; flow:to_server; sid:1; rev:1;)\ndrop udp any any -> any 23 (msg:\"layer 7 rule 2\"; flow:to_server; sid:2; rev:1;)\ndrop ip any any -> 198.51.100.0/24 any (msg:\"layer 7 rule 3\"; flow:to_server; sid:3; rev:1;)\ndrop ip any any -> [$VLAN_30_,172.16.40.0/24] any (msg:\"ot cell isolated\"; flow:to_server; sid:4; rev:1;)\ndrop ip [10.10.30.0/24,172.16.40.0/24] any -> any any (msg:\"ot no internet\"; flow:to_server; sid:5; rev:1;)\n"
 },
 "StatefulRuleOptions": {
  "RuleOrder": "STRICT_ORDER"
 }
}
FWSHIFT_JSON
G1=$(group fwshift-rules 100 "$TMP/group1.json") || exit 1

# The policy: every packet to the stateful engine, the rule groups in strict order, then the default of the source.
cat > "$TMP/policy.json" <<FWSHIFT_JSON
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"},"StatefulRuleGroupReferences":[{"ResourceArn":"${G1}","Priority":100}]}
FWSHIFT_JSON
cat > "$TMP/policy-check.json" <<'FWSHIFT_JSON'
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"}}
FWSHIFT_JSON
policy fwshift "$TMP/policy.json" "$TMP/policy-check.json"

# Not written:
#   inside a VLAN: intrazone rule: a rule of Network Firewall names no zones; the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network; the destination of the
#   office to servers web: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   historian: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   eng ws to plc: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   block update site: host name object fqdn updates.example.com: a rule of Network Firewall names addresses (a domain list matches TLS and HTTP names, which is something else)
#   dns to servers: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   ping servers: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   office ipv6 out: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   passive ftp: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   bad ports: not converted: destination port '1024-5000,5004' cannot be read (one range, or a list of single ports); the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cel
#   Default rule: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Network Firewall names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   vpn-portal: the source of the rule is in zone internet, and a rule of Network Firewall names no zone: give the networks behind internet with --zone-network; the destination of the rule is in zone vlan20-servers, and a rule of Network Firewall names no zone: give the networks behind vlan20-servers with --zone-ne
#   mail (1): the source of the rule is in zone internet, and a rule of Network Firewall names no zone: give the networks behind internet with --zone-network; the destination of the rule is in zone vlan20-servers, and a rule of Network Firewall names no zone: give the networks behind vlan20-servers with --zone-ne
#   mail (2): the source of the rule is in zone internet, and a rule of Network Firewall names no zone: give the networks behind internet with --zone-network; the destination of the rule is in zone vlan20-servers, and a rule of Network Firewall names no zone: give the networks behind vlan20-servers with --zone-ne
#   scada-view: the source of the rule is in zone internet, and a rule of Network Firewall names no zone: give the networks behind internet with --zone-network; the destination of the rule is in zone vlan20-servers, and a rule of Network Firewall names no zone: give the networks behind vlan20-servers with --zone-ne

echo 'Done. Associate the policy with a firewall when you are ready; until then nothing changes.' >&2
